"""Random arrays for the sum problem: a count line, then the values.

Values stay well inside a 32-bit int -- at most a dozen of them, none past a
thousand -- so a correct C solution cannot overflow on generated data. An
input that made the answer depend on undefined behaviour would not have a
defensible expected output.
"""


def generate(rng, count):
    builders = (_positive, _mixed_signs, _all_negative, _longer)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values), " ".join(str(v) for v in values)),
        "description": description,
    }


def _positive(rng, index):
    values = [rng.randint(1, 200) for _ in range(rng.randint(4, 8))]
    return _case("positive values #%d" % index, values)


def _mixed_signs(rng, index):
    values = [rng.randint(-150, 150) for _ in range(rng.randint(4, 9))]
    return _case("mixed signs #%d" % index, values)


def _all_negative(rng, index):
    values = [rng.randint(-300, -1) for _ in range(rng.randint(3, 7))]
    return _case("all negative #%d" % index, values,
                 "The total is negative; nothing here is clamped at zero.")


def _longer(rng, index):
    values = [rng.randint(-999, 999) for _ in range(rng.randint(10, 12))]
    return _case("a longer array #%d" % index, values)
